verifyCmd:
node <<'VERIFYJS'
const p = require('./parseCookie.js');
const S = JSON.stringify;
const eq = (got, want, m) => { if (S(got) !== S(want)) { console.error('FAIL', m, S(got)); process.exit(1); } };
eq(p('a=1; b=2'), { a: '1', b: '2' }, 'basic');
eq(p('  a = 1 ;b=2'), { a: '1', b: '2' }, 'trimming');
eq(p('a=b=c'), { a: 'b=c' }, 'first = splits');
eq(p('a="quoted"'), { a: 'quoted' }, 'quotes stripped');
eq(p('a=hello%20world'), { a: 'hello world' }, 'url decoded');
eq(p('a=%E4%B8%AD'), { a: '中' }, 'utf8 decoded');
eq(p('a=%zz'), { a: '%zz' }, 'malformed escape kept verbatim');
eq(p('a=1; a=2'), { a: '1' }, 'first duplicate wins');
eq(p('novalue; a=1'), { a: '1' }, 'segment without = skipped');
eq(p('=noname; a=1'), { a: '1' }, 'empty name skipped');
eq(p(''), {}, 'empty header');
eq(p(null), {}, 'non-string');
eq(p('a='), { a: '' }, 'empty value');
eq(p('a="1'), { a: '"1' }, 'unbalanced quote kept');
console.log('ok');
VERIFYJS
